sp_widget.client_script:
api.controller = function($scope, $window, $timeout) {

  var c = this;

  /* =====================================================
     STATE
     ===================================================== */

  c.sidebarCollapsed = false;
  c.loading = false;
  c.saving = false;

  c.showApplicationModal = false;
  c.showNotificationModal = false;

  c.selectedApplication = null;

  c.updateMessage = "";
  c.updateSuccess = false;


  /* =====================================================
     NOTIFICATION STATE
     ===================================================== */

  c.notification = {
    sending: false,
    message: "",
    success: false
  };


  /* =====================================================
     FILTERS
     ===================================================== */

  c.filters = {
    search: "",
    company: "",
    country: "",
    applicationStatus: "",
    studentResponse: "",
    shortlisted: "",
    assessmentStatus: "",
    interviewStatus: "",
    offerStatus: ""
  };

  c.filteredApplications = [];


  /* =====================================================
     SIDEBAR
     ===================================================== */

  c.toggleSidebar = function() {
    c.sidebarCollapsed = !c.sidebarCollapsed;
  };


  /* =====================================================
     NAVIGATION
     ===================================================== */

  c.goTo = function(pageId) {

    if (!pageId) {
      return;
    }

    var map = {

      dashboard: "campus360_tpo_home",
      home: "campus360_tpo_home",
      campus360_tpo_home: "campus360_tpo_home",

      students: "campus360_tpo_student_management",
      student_management: "campus360_tpo_student_management",
      campus360_tpo_student_management:
        "campus360_tpo_student_management",

      skills: "campus360_tpo_skill_intelligence_new",
      skill_intelligence: "campus360_tpo_skill_intelligence_new",
      campus360_tpo_skill_intelligence:
        "campus360_tpo_skill_intelligence_new",
      campus360_tpo_skill_intelligence_new:
        "campus360_tpo_skill_intelligence_new",

      assessments: "student_assessments_new",
      student_assessments: "student_assessments_new",
      student_assessments_new: "student_assessments_new",

      companies: "campus360_tpo_companies_new",
      campus360_tpo_companies: "campus360_tpo_companies_new",
      campus360_tpo_companies_new:
        "campus360_tpo_companies_new",

      opportunities: "campus360_tpo_opportunities_new",
      campus360_tpo_opportunities:
        "campus360_tpo_opportunities_new",
      campus360_tpo_opportunities_new:
        "campus360_tpo_opportunities_new",

      applications: "campus360_tpo_application_new",
      application: "campus360_tpo_application_new",
      campus360_tpo_application:
        "campus360_tpo_application_new",
      campus360_tpo_application_new:
        "campus360_tpo_application_new",

      interviews: "campus360_tpo_interviews_new",
      campus360_tpo_interviews:
        "campus360_tpo_interviews_new",
      campus360_tpo_interviews_new:
        "campus360_tpo_interviews_new",

      outcomes: "campus360_tpo_placement_outcomes",
      placement_outcomes:
        "campus360_tpo_placement_outcomes",
      campus360_tpo_placement_outcomes:
        "campus360_tpo_placement_outcomes",

      training: "campus360_tpo_training_programs",
      training_programs:
        "campus360_tpo_training_programs",
      campus360_tpo_training_programs:
        "campus360_tpo_training_programs",

      enrollments:
        "campus360_tpo_training_programs",

      campus360_tpo_enrollments:
        "campus360_tpo_training_programs",

      mock_interviews:
        "campus360_tpo_interviews_new",

      campus360_tpo_mock_interviews:
        "campus360_tpo_interviews_new",

      risk:
        "campus360_tpo_student_management",

      campus360_tpo_risk_intelligence:
        "campus360_tpo_student_management",

      interventions:
        "campus360_tpo_student_management",

      campus360_tpo_interventions:
        "campus360_tpo_student_management",

      readiness:
        "campus360_tpo_skill_intelligence_new",

      ai_assistant:
        "campus360_tpo_ai_assistant",

      campus360_tpo_ai_assistant:
        "campus360_tpo_ai_assistant"
    };

    var target = map[pageId] || pageId;

    $window.location.href =
      "?id=" + encodeURIComponent(target);
  };


  c.goToPage = function(pageId) {
    c.goTo(pageId);
  };


  c.navigate = function(pageId) {
    c.goTo(pageId);
  };


  /* =====================================================
     APPLY FILTERS
     ===================================================== */

  c.applyFilters = function() {

    var search =
      String(c.filters.search || "")
        .toLowerCase()
        .trim();

    c.filteredApplications =
      (c.data.applications || [])
        .filter(function(a) {

          var searchable = [

            a.application_id,
            a.number,

            a.student_name,
            a.student_id,
            a.student_email,

            a.opportunity_title,
            a.opportunity_id,

            a.company_name,
            a.country

          ]
            .join(" ")
            .toLowerCase();


          var searchOK =
            !search ||
            searchable.indexOf(search) !== -1;


          var companyOK =
            !c.filters.company ||
            String(a.company_name || "") ===
            String(c.filters.company);


          var countryOK =
            !c.filters.country ||
            String(a.country || "") ===
            String(c.filters.country);


          var statusOK =
            !c.filters.applicationStatus ||
            String(a.application_status_value || "") ===
            String(c.filters.applicationStatus);


          var responseOK =
            !c.filters.studentResponse ||
            String(a.student_response_value || "") ===
            String(c.filters.studentResponse);


          var shortlistedOK =
            c.filters.shortlisted === "" ||
            Boolean(a.shortlisted) ===
            (c.filters.shortlisted === "true");


          var assessmentOK =
            !c.filters.assessmentStatus ||
            String(a.assessment_status_value || "") ===
            String(c.filters.assessmentStatus);


          var interviewOK =
            !c.filters.interviewStatus ||
            String(a.interview_status_value || "") ===
            String(c.filters.interviewStatus);


          var offerOK =
            !c.filters.offerStatus ||
            String(a.offer_status_value || "") ===
            String(c.filters.offerStatus);


          return (
            searchOK &&
            companyOK &&
            countryOK &&
            statusOK &&
            responseOK &&
            shortlistedOK &&
            assessmentOK &&
            interviewOK &&
            offerOK
          );

        });
  };


  /* =====================================================
     CLEAR FILTERS
     ===================================================== */

  c.clearFilters = function() {

    c.filters = {
      search: "",
      company: "",
      country: "",
      applicationStatus: "",
      studentResponse: "",
      shortlisted: "",
      assessmentStatus: "",
      interviewStatus: "",
      offerStatus: ""
    };

    c.applyFilters();
  };


  /* =====================================================
     REFRESH DATA
     ===================================================== */

  c.refreshData = function() {

    if (c.loading) {
      return;
    }

    c.loading = true;

    c.server.get({
      action: "refresh"
    }).then(

      function(response) {

        if (response && response.data) {
          c.data = response.data;
        }

        c.loading = false;
        c.applyFilters();

      },

      function() {
        c.loading = false;
      }

    );
  };


  /* =====================================================
     NOTIFICATION MODAL
     ===================================================== */

  c.openNotificationModal = function(event) {

    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }

    c.showNotificationModal = true;

    c.notification.message = "";
    c.notification.success = false;

    c.refreshNotificationSummary();
  };


  c.closeNotificationModal = function(event) {

    if (event) {

      if (
        event.target !== event.currentTarget &&
        event.currentTarget.className &&
        String(event.currentTarget.className)
          .indexOf("notification-modal-backdrop") === -1
      ) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
    }

    c.showNotificationModal = false;
  };


  c.toggleNotificationDropdown = function(event) {

    if (c.showNotificationModal) {
      c.closeNotificationModal(event);
    } else {
      c.openNotificationModal(event);
    }
  };


  /* =====================================================
     NOTIFICATION SUMMARY
     ===================================================== */

  c.refreshNotificationSummary = function() {

    c.server.get({
      action: "notification_summary"
    }).then(

      function(response) {

        if (response && response.data) {

          c.data = response.data;

          if (!c.data.notification) {
            c.data.notification = {
              eligibleStudents: 0,
              eligibleOpportunities: 0
            };
          }

          c.applyFilters();
        }

      },

      function() {

        if (!c.data.notification) {
          c.data.notification = {
            eligibleStudents: 0,
            eligibleOpportunities: 0
          };
        }

      }

    );
  };


  /* =====================================================
     SEND ELIGIBLE STUDENT NOTIFICATIONS
     ===================================================== */

  c.sendEligibleNotifications = function() {

    if (c.notification.sending) {
      return;
    }

    c.notification.sending = true;
    c.notification.message = "";
    c.notification.success = false;


    c.server.get({
      action: "notify_eligible_students"
    }).then(

      function(response) {

        c.notification.sending = false;

        if (
          response &&
          response.data
        ) {

          c.data = response.data;

          if (response.data.notificationResult) {

            var result =
              response.data.notificationResult;

            c.notification.success =
              Boolean(result.success);

            c.notification.message =
              result.message || "";

          }

          if (!c.data.notification) {

            c.data.notification = {
              eligibleStudents: 0,
              eligibleOpportunities: 0
            };

          }

          c.applyFilters();

        } else {

          c.notification.success = false;

          c.notification.message =
            "Unable to process student notifications.";

        }

      },

      function() {

        c.notification.sending = false;

        c.notification.success = false;

        c.notification.message =
          "Unable to send student notifications.";

      }

    );
  };


  /* =====================================================
     COMPATIBILITY ALIAS
     ===================================================== */

  c.sendNotifications = function() {
    c.sendEligibleNotifications();
  };


  /* =====================================================
     OPEN APPLICATION
     ===================================================== */

  c.openApplication = function(application) {

    if (!application) {
      return;
    }

    c.selectedApplication =
      angular.copy(application);

    c.updateMessage = "";
    c.updateSuccess = false;

    c.showApplicationModal = true;
  };


  /* =====================================================
     CLOSE APPLICATION
     ===================================================== */

  c.closeApplication = function(event) {

    if (
      event &&
      event.target !== event.currentTarget
    ) {
      return;
    }

    if (c.saving) {
      return;
    }

    c.showApplicationModal = false;
    c.selectedApplication = null;

    c.updateMessage = "";
    c.updateSuccess = false;
  };


  /* =====================================================
     INITIALS
     ===================================================== */

  c.getInitials = function(name) {

    if (!name) {
      return "ST";
    }

    var parts =
      String(name)
        .trim()
        .split(/\s+/);

    if (parts.length === 1) {

      return parts[0]
        .substring(0, 2)
        .toUpperCase();
    }

    return (
      parts[0].charAt(0) +
      parts[parts.length - 1].charAt(0)
    ).toUpperCase();
  };


  /* =====================================================
     STATUS CLASS
     ===================================================== */

  c.getStatusClass = function(status) {

    var value =
      String(status || "")
        .toLowerCase();


    if (value.indexOf("pending") !== -1) {
      return "status-pending";
    }


    if (
      value.indexOf("approved") !== -1 ||
      value.indexOf("selected") !== -1 ||
      value.indexOf("accepted") !== -1 ||
      value.indexOf("shortlisted") !== -1
    ) {
      return "status-approved";
    }


    if (value.indexOf("reject") !== -1) {
      return "status-rejected";
    }


    if (value.indexOf("withdraw") !== -1) {
      return "status-withdrawn";
    }


    return "status-default";
  };


  /* =====================================================
     RESPONSE CLASS
     ===================================================== */

  c.getResponseClass = function(response) {

    var value =
      String(response || "")
        .toLowerCase();


    if (
      value === "apply" ||
      value.indexOf("interested") !== -1
    ) {
      return "response-positive";
    }


    if (
      value === "ignored" ||
      value.indexOf("not interested") !== -1
    ) {
      return "response-negative";
    }


    if (value === "pending") {
      return "response-neutral";
    }


    return "response-default";
  };


  /* =====================================================
     SHOW ASSESSMENT
     ===================================================== */

  c.shouldShowAssessment = function(a) {

    if (!a) {
      return false;
    }

    if (!a.shortlisted) {
      return false;
    }

    var status =
      String(a.application_status || "")
        .toLowerCase();

    var response =
      String(a.student_response || "")
        .toLowerCase();


    if (
      status.indexOf("reject") !== -1 ||
      status.indexOf("withdraw") !== -1
    ) {
      return false;
    }


    if (
      response === "not interested" ||
      response === "ignored"
    ) {
      return false;
    }


    return true;
  };


  /* =====================================================
     SHOW INTERVIEW
     ===================================================== */

  c.shouldShowInterview = function(a) {

    if (!c.shouldShowAssessment(a)) {
      return false;
    }

    var assessment =
      String(a.assessment_status || "")
        .toLowerCase();


    if (
      !assessment ||
      assessment === "not started"
    ) {
      return false;
    }


    if (
      assessment.indexOf("fail") !== -1 ||
      assessment.indexOf("reject") !== -1
    ) {
      return false;
    }


    return true;
  };


  /* =====================================================
     SHOW OFFER
     ===================================================== */

  c.shouldShowOffer = function(a) {

    if (!c.shouldShowInterview(a)) {
      return false;
    }

    var interview =
      String(a.interview_status || "")
        .toLowerCase();


    if (
      !interview ||
      interview === "not scheduled"
    ) {
      return false;
    }


    if (
      interview.indexOf("reject") !== -1 ||
      interview.indexOf("cancel") !== -1
    ) {
      return false;
    }


    return true;
  };


  /* =====================================================
     UPDATE APPLICATION
     ===================================================== */

  c.updateApplication = function() {

    if (!c.selectedApplication) {
      return;
    }

    c.saving = true;
    c.updateMessage = "";
    c.updateSuccess = false;


    c.server.get({

      action: "update_application",

      application: {

        sys_id:
          c.selectedApplication.sys_id,

        application_status:
          c.selectedApplication.application_status_value || "",

        student_response:
          c.selectedApplication.student_response_value || "",

        shortlisted:
          Boolean(
            c.selectedApplication.shortlisted
          ),

        assessment_status:
          c.selectedApplication.assessment_status_value || "",

        interview_status:
          c.selectedApplication.interview_status_value || "",

        offer_status:
          c.selectedApplication.offer_status_value || ""
      }

    }).then(

      function(response) {

        c.saving = false;


        if (
          response &&
          response.data &&
          response.data.updateResult
        ) {

          var result =
            response.data.updateResult;


          if (result.success) {

            c.updateSuccess = true;

            c.updateMessage =
              result.message;


            c.data =
              response.data;


            if (result.application) {

              c.selectedApplication =
                angular.copy(
                  result.application
                );

            }


            c.applyFilters();

          } else {

            c.updateSuccess = false;

            c.updateMessage =
              result.message;

          }

        } else {

          c.updateSuccess = false;

          c.updateMessage =
            "Unable to update application.";

        }

      },

      function() {

        c.saving = false;

        c.updateSuccess = false;

        c.updateMessage =
          "Unable to update application.";

      }

    );
  };


  /* =====================================================
     ESCAPE KEY
     ===================================================== */

  var escapeHandler = function(event) {

    if (event.key !== "Escape") {
      return;
    }


    if (
      c.showNotificationModal
    ) {

      $scope.$evalAsync(function() {
        c.showNotificationModal = false;
      });

      return;
    }


    if (
      c.showApplicationModal &&
      !c.saving
    ) {

      $scope.$evalAsync(function() {

        c.showApplicationModal = false;
        c.selectedApplication = null;

      });
    }
  };


  $window.addEventListener(
    "keydown",
    escapeHandler
  );


  $scope.$on(
    "$destroy",
    function() {

      $window.removeEventListener(
        "keydown",
        escapeHandler
      );

    }
  );


  /* =====================================================
     INITIALIZE
     ===================================================== */

  if (!c.data.notification) {

    c.data.notification = {
      eligibleStudents: 0,
      eligibleOpportunities: 0
    };

  }

  c.applyFilters();

};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

html,
body {
  width:100% !important;
  height:100% !important;
  margin:0 !important;
  padding:0 !important;
  overflow:hidden !important;
  background:#f8fafc !important;
}

body #sp-header,
body .sp-header,
body .sp-navbar,
body #sp-nav-bar,
body .sp-nav-bar,
body header.navbar,
body nav.navbar,
body .navbar,
body .navbar-fixed-top,
body .navbar-default,
body .navbar-inverse {
  display:none !important;
  height:0 !important;
  min-height:0 !important;
  margin:0 !important;
  padding:0 !important;
  overflow:hidden !important;
}

body .page,
body #sp-page,
body #sp-main,
body .sp-page,
body .sp-main,
body .page-wrapper,
body .main-content,
body .container,
body .container-fluid,
body .row,
body [class*="col-"] {
  width:100% !important;
  max-width:none !important;
  margin:0 !important;
  padding:0 !important;
  border:0 !important;
}

.campus360-applications-app,
.campus360-applications-app * {
  box-sizing:border-box !important;
}

.campus360-applications-app {
  --purple:#7c3aed;
  --purple-dark:#6d28d9;
  --navy:#121126;
  --text:#172033;
  --muted:#728096;
  --border:#e2e7ed;
  --bg:#f8fafc;
  --white:#ffffff;
  --teal:#0f766e;
  --teal-light:#ccfbf1;
  --rose:#e11d48;
  --rose-light:#ffe4e6;
  --amber:#d97706;
  --amber-light:#fef3c7;
  --indigo:#4f46e5;
  --indigo-light:#e0e7ff;

  position:fixed !important;
  inset:0 !important;
  width:100vw !important;
  height:100vh !important;
  display:flex !important;
  overflow:hidden !important;
  background:var(--bg) !important;
  color:var(--text) !important;
  font-family:'Plus Jakarta Sans',Arial,sans-serif !important;
  font-size:14px !important;
  line-height:1.45 !important;
  z-index:999999 !important;
}

/* ================= SIDEBAR ================= */

.applications-sidebar {
  width:275px !important;
  min-width:275px !important;
  height:100vh !important;
  display:flex !important;
  flex-direction:column !important;
  background:linear-gradient(180deg,#111025,#100e22) !important;
  color:#fff !important;
  border-right:1px solid rgba(255,255,255,.05) !important;
  box-shadow:4px 0 24px rgba(0,0,0,.12) !important;
  transition:.25s ease !important;
  z-index:100 !important;
}

.sidebar-brand {
  height:84px !important;
  min-height:84px !important;
  padding:18px 20px !important;
  display:flex !important;
  align-items:center !important;
  gap:13px !important;
  border-bottom:1px solid rgba(255,255,255,.05) !important;
}

.brand-mark {
  width:44px !important;
  height:44px !important;
  min-width:44px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border-radius:13px !important;
  background:linear-gradient(135deg,#8b5cf6,#6d28d9) !important;
  color:#fff !important;
  font-size:25px !important;
  font-weight:900 !important;
}

.brand-title {
  color:#fff !important;
  font-size:19px !important;
  font-weight:800 !important;
}

.brand-subtitle {
  margin-top:4px !important;
  color:#bcaeff !important;
  font-size:10px !important;
  font-weight:800 !important;
  text-transform:uppercase !important;
  letter-spacing:.7px !important;
}

.sidebar-user-card {
  margin:16px 18px 9px !important;
  padding:13px 12px !important;
  min-height:66px !important;
  display:flex !important;
  align-items:center !important;
  gap:11px !important;
  border:1px solid rgba(124,58,237,.28) !important;
  border-radius:15px !important;
  background:rgba(124,58,237,.14) !important;
}

.sidebar-user-avatar {
  width:42px !important;
  height:42px !important;
  min-width:42px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border-radius:50% !important;
  background:linear-gradient(135deg,#8b5cf6,#6d28d9) !important;
  color:#fff !important;
  font-size:12px !important;
  font-weight:800 !important;
}

.sidebar-user-name {
  color:#fff !important;
  font-size:13px !important;
  font-weight:800 !important;
}

.sidebar-user-role {
  margin-top:4px !important;
  color:#b9b5cf !important;
  font-size:9px !important;
}

.sidebar-scroll {
  flex:1 !important;
  min-height:0 !important;
  padding:5px 13px 16px !important;
  overflow-y:auto !important;
  scrollbar-width:none !important;
}

.sidebar-scroll::-webkit-scrollbar {
  display:none !important;
}

.menu-section-title {
  margin:16px 12px 7px !important;
  color:#9995b0 !important;
  font-size:10px !important;
  font-weight:800 !important;
  letter-spacing:.65px !important;
}

.menu-item {
  width:100% !important;
  min-height:42px !important;
  margin:3px 0 !important;
  padding:0 12px !important;
  display:flex !important;
  align-items:center !important;
  gap:10px !important;
  border:0 !important;
  border-radius:11px !important;
  background:transparent !important;
  color:#d9d6e6 !important;
  font-size:13px !important;
  font-weight:600 !important;
  text-align:left !important;
  cursor:pointer !important;
  transition:.18s ease !important;
}

.menu-item:hover {
  background:rgba(255,255,255,.07) !important;
  color:#fff !important;
  transform:translateX(2px);
}

.menu-item.active {
  background:linear-gradient(90deg,#7c3aed,#8338ec) !important;
  color:#fff !important;
  box-shadow:0 8px 20px rgba(124,58,237,.25) !important;
}

.menu-icon {
  width:20px !important;
  min-width:20px !important;
  color:#aaa6bd !important;
  text-align:center !important;
}

.menu-item:hover .menu-icon,
.menu-item.active .menu-icon {
  color:#fff !important;
}

.menu-count {
  min-width:25px !important;
  height:22px !important;
  margin-left:auto !important;
  padding:0 7px !important;
  display:inline-flex !important;
  align-items:center !important;
  justify-content:center !important;
  border-radius:20px !important;
  background:rgba(124,58,237,.35) !important;
  color:#d8b4fe !important;
  font-size:10px !important;
  font-weight:800 !important;
}

.menu-item.active .menu-count {
  background:rgba(255,255,255,.2) !important;
  color:#fff !important;
}

.sidebar-footer {
  padding:13px 10px 17px !important;
  border-top:1px solid rgba(255,255,255,.05) !important;
  color:#8c889e !important;
  font-family:monospace !important;
  font-size:9px !important;
  text-align:center !important;
}

/* ================= MAIN ================= */

.applications-main {
  flex:1 1 auto !important;
  min-width:0 !important;
  height:100vh !important;
  display:flex !important;
  flex-direction:column !important;
  overflow:hidden !important;
  background:#f8fafc !important;
}

/* ================= TOPBAR ================= */

.applications-topbar {
  height:69px !important;
  min-height:69px !important;
  padding:0 25px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;
  background:#fff !important;
  border-bottom:1px solid #e2e7ed !important;
  position:relative !important;
  z-index:200 !important;
}

.topbar-left,
.topbar-right {
  display:flex !important;
  align-items:center !important;
}

.topbar-right {
  gap:9px !important;
}

.sidebar-toggle {
  width:38px !important;
  height:38px !important;
  margin-right:15px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border:1px solid #dfe4ec !important;
  border-radius:10px !important;
  background:#fff !important;
  color:#657286 !important;
  cursor:pointer !important;
}

.sidebar-toggle:hover {
  color:#6d28d9 !important;
  border-color:#cbb8f4 !important;
  background:#faf7ff !important;
}

.topbar-page-eyebrow {
  color:#7c3aed !important;
  font-size:9px !important;
  font-weight:800 !important;
  letter-spacing:1px !important;
}

.topbar-page-title {
  margin-top:2px !important;
  color:#172033 !important;
  font-size:16px !important;
  font-weight:800 !important;
}

.topbar-search {
  width:min(360px,28vw) !important;
  height:39px !important;
  padding:0 12px !important;
  display:flex !important;
  align-items:center !important;
  border:1px solid #dfe4ec !important;
  border-radius:11px !important;
  background:#f8fafc !important;
}

.topbar-search:focus-within {
  background:#fff !important;
  border-color:#bda7f1 !important;
  box-shadow:0 0 0 3px rgba(124,58,237,.07) !important;
}

.topbar-search i {
  margin-right:9px !important;
  color:#8a96a8 !important;
}

.topbar-search input {
  width:100% !important;
  height:100% !important;
  border:0 !important;
  outline:0 !important;
  background:transparent !important;
  font-size:11px !important;
}

.topbar-circle-button {
  position:relative !important;
  width:38px !important;
  height:38px !important;
  display:inline-flex !important;
  align-items:center !important;
  justify-content:center !important;
  border:1px solid #dfe4ec !important;
  border-radius:11px !important;
  background:#fff !important;
  color:#59677b !important;
  cursor:pointer !important;
}

.topbar-circle-button:hover {
  color:#6d28d9 !important;
  border-color:#cbb8f4 !important;
  background:#faf7ff !important;
}

/* ================= BELL ================= */

.notification-button {
  position:relative !important;
  z-index:300 !important;
  cursor:pointer !important;
}

.notification-bell-icon {
  display:inline-block !important;
  color:#475569 !important;
  font-size:16px !important;
  pointer-events:none !important;
}

.notification-button:hover .notification-bell-icon {
  color:#0f766e !important;
}

.notification-badge {
  position:absolute !important;
  top:-5px !important;
  right:-5px !important;
  min-width:17px !important;
  height:17px !important;
  padding:0 4px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border:2px solid #fff !important;
  border-radius:12px !important;
  background:#e11d48 !important;
  color:#fff !important;
  font-size:8px !important;
  font-weight:900 !important;
  z-index:500 !important;
  pointer-events:none !important;
}

/* ================= PROFILE ================= */

.topbar-profile {
  display:flex !important;
  align-items:center !important;
  gap:9px !important;
  padding-left:5px !important;
}

.topbar-avatar {
  width:35px !important;
  height:35px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border-radius:50% !important;
  background:linear-gradient(135deg,#7c3aed,#4f46e5) !important;
  color:#fff !important;
  font-size:10px !important;
  font-weight:800 !important;
}

.topbar-profile-name {
  color:#172033 !important;
  font-size:11px !important;
  font-weight:800 !important;
}

.topbar-profile-role {
  color:#8994a5 !important;
  font-size:9px !important;
}

.profile-arrow {
  color:#8b96a7 !important;
}

/* ================= CONTENT ================= */

.applications-content {
  flex:1 !important;
  min-height:0 !important;
  overflow-y:auto !important;
  overflow-x:hidden !important;
  padding:28px 30px 50px !important;
}

.page-heading {
  display:flex !important;
  align-items:flex-end !important;
  justify-content:space-between !important;
  gap:25px !important;
  margin-bottom:22px !important;
}

.page-eyebrow,
.directory-eyebrow {
  color:#0f766e !important;
  font-size:10px !important;
  font-weight:900 !important;
  letter-spacing:1px !important;
}

.page-eyebrow {
  display:flex !important;
  align-items:center !important;
  gap:7px !important;
}

.eyebrow-dot {
  width:7px !important;
  height:7px !important;
  border-radius:50% !important;
  background:#0f766e !important;
}

.page-heading h1 {
  margin:7px 0 5px !important;
  color:#111827 !important;
  font-size:30px !important;
  line-height:1.1 !important;
  font-weight:800 !important;
  letter-spacing:-.8px !important;
}

.page-heading p {
  margin:0 !important;
  color:#728096 !important;
  font-size:12px !important;
}

.page-heading-actions {
  display:flex !important;
  gap:10px !important;
}

.outline-button {
  height:40px !important;
  padding:0 15px !important;
  display:inline-flex !important;
  align-items:center !important;
  gap:8px !important;
  border:1px solid #d6dde7 !important;
  border-radius:10px !important;
  background:#fff !important;
  color:#475569 !important;
  font-size:11px !important;
  font-weight:700 !important;
  cursor:pointer !important;
}

.outline-button:hover {
  border-color:#0f766e !important;
  color:#0f766e !important;
  background:#f0fdfa !important;
}

/* ================= NOTIFICATION SUMMARY ================= */

.notification-panel {
  margin-bottom:20px !important;
  padding:17px 20px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;
  gap:20px !important;
  border:1px solid #99f6e4 !important;
  border-radius:15px !important;
  background:linear-gradient(135deg,#f0fdfa,#ffffff) !important;
}

.notification-panel-left {
  display:flex !important;
  align-items:center !important;
  gap:14px !important;
}

.notification-icon {
  width:46px !important;
  height:46px !important;
  min-width:46px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border-radius:13px !important;
  background:#ccfbf1 !important;
  color:#0f766e !important;
  font-size:18px !important;
}

.notification-panel-title {
  color:#134e4a !important;
  font-size:13px !important;
  font-weight:800 !important;
}

.notification-panel-text {
  margin-top:4px !important;
  color:#64748b !important;
  font-size:10px !important;
}

.notification-stats {
  display:flex !important;
  align-items:center !important;
  gap:18px !important;
}

.notification-stat {
  min-width:95px !important;
  text-align:center !important;
}

.notification-stat-value {
  display:block !important;
  color:#0f766e !important;
  font-size:21px !important;
  font-weight:900 !important;
}

.notification-stat-label {
  display:block !important;
  margin-top:2px !important;
  color:#64748b !important;
  font-size:9px !important;
  font-weight:700 !important;
}

.notification-send-button {
  height:38px !important;
  padding:0 14px !important;
  border:0 !important;
  border-radius:9px !important;
  background:#0f766e !important;
  color:#fff !important;
  font-size:10px !important;
  font-weight:800 !important;
  cursor:pointer !important;
}

.notification-send-button:hover {
  background:#115e59 !important;
}

.notification-send-button:disabled {
  opacity:.55 !important;
  cursor:not-allowed !important;
}

/* ================= KPI ================= */

.kpi-grid {
  display:grid !important;
  grid-template-columns:repeat(4,minmax(0,1fr)) !important;
  gap:15px !important;
  margin-bottom:20px !important;
}

.kpi-card {
  min-height:142px !important;
  padding:19px !important;
  display:flex !important;
  align-items:center !important;
  gap:15px !important;
  border-radius:16px !important;
  border:1px solid transparent !important;
  background:#fff !important;
  box-shadow:0 7px 25px rgba(26,31,54,.05) !important;
}

.kpi-icon {
  width:48px !important;
  height:48px !important;
  min-width:48px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border-radius:14px !important;
  font-size:19px !important;
}

.kpi-content {
  min-width:0 !important;
}

.kpi-label {
  font-size:9px !important;
  font-weight:900 !important;
  letter-spacing:.7px !important;
  line-height:1.35 !important;
}

.kpi-value {
  margin-top:6px !important;
  font-size:29px !important;
  line-height:1 !important;
  font-weight:900 !important;
}

.kpi-description {
  margin-top:7px !important;
  font-size:9px !important;
  color:#7a8798 !important;
}

.kpi-teal {
  border-color:#99f6e4 !important;
  background:linear-gradient(135deg,#f0fdfa,#fff) !important;
}

.kpi-teal .kpi-icon {
  background:#ccfbf1 !important;
  color:#0f766e !important;
}

.kpi-teal .kpi-label,
.kpi-teal .kpi-value {
  color:#0f766e !important;
}

.kpi-rose {
  border-color:#fecdd3 !important;
  background:linear-gradient(135deg,#fff1f2,#fff) !important;
}

.kpi-rose .kpi-icon {
  background:#ffe4e6 !important;
  color:#e11d48 !important;
}

.kpi-rose .kpi-label,
.kpi-rose .kpi-value {
  color:#be123c !important;
}

.kpi-amber {
  border-color:#fde68a !important;
  background:linear-gradient(135deg,#fffbeb,#fff) !important;
}

.kpi-amber .kpi-icon {
  background:#fef3c7 !important;
  color:#d97706 !important;
}

.kpi-amber .kpi-label,
.kpi-amber .kpi-value {
  color:#b45309 !important;
}

.kpi-indigo {
  border-color:#c7d2fe !important;
  background:linear-gradient(135deg,#eef2ff,#fff) !important;
}

.kpi-indigo .kpi-icon {
  background:#e0e7ff !important;
  color:#4f46e5 !important;
}

.kpi-indigo .kpi-label,
.kpi-indigo .kpi-value {
  color:#4338ca !important;
}

/* ================= FILTERS ================= */

.filter-bar {
  min-height:64px !important;
  padding:10px !important;
  display:flex !important;
  align-items:center !important;
  gap:9px !important;
  flex-wrap:wrap !important;
  border:1px solid #e2e7ed !important;
  border-radius:14px 14px 0 0 !important;
  background:#fff !important;
}

.filter-record-count {
  min-width:100px !important;
  padding:0 8px !important;
}

.filter-count-label {
  display:block !important;
  color:#0f766e !important;
  font-size:8px !important;
  font-weight:900 !important;
  letter-spacing:.7px !important;
}

.filter-record-count strong {
  color:#172033 !important;
  font-size:18px !important;
}

.filter-count-text {
  color:#8994a5 !important;
  font-size:9px !important;
}

.filter-search {
  flex:1 1 270px !important;
  height:38px !important;
  padding:0 11px !important;
  display:flex !important;
  align-items:center !important;
  border:1px solid #dfe4ec !important;
  border-radius:9px !important;
  background:#f8fafc !important;
}

.filter-search-icon {
  margin-right:8px !important;
  color:#8994a5 !important;
}

.filter-search input {
  width:100% !important;
  border:0 !important;
  outline:0 !important;
  background:transparent !important;
  font-size:10px !important;
}

.filter-select,
.secondary-select {
  height:38px !important;
  padding:0 10px !important;
  border:1px solid #dfe4ec !important;
  border-radius:9px !important;
  background:#fff !important;
  color:#475569 !important;
  font-size:10px !important;
  outline:0 !important;
}

.filter-select {
  min-width:135px !important;
}

.clear-button {
  height:38px !important;
  padding:0 13px !important;
  border:1px solid #fecdd3 !important;
  border-radius:9px !important;
  background:#fff1f2 !important;
  color:#be123c !important;
  font-size:10px !important;
  font-weight:800 !important;
  cursor:pointer !important;
}

.secondary-filter-bar {
  padding:11px 13px !important;
  display:flex !important;
  align-items:center !important;
  gap:9px !important;
  flex-wrap:wrap !important;
  border:1px solid #e2e7ed !important;
  border-top:0 !important;
  background:#f8fafc !important;
}

.secondary-filter-label {
  color:#64748b !important;
  font-size:9px !important;
  font-weight:900 !important;
  letter-spacing:.6px !important;
  margin-right:5px !important;
}

.secondary-select {
  min-width:145px !important;
}

/* ================= DIRECTORY ================= */

.directory-card {
  margin-top:20px !important;
  overflow:hidden !important;
  border:1px solid #dce4e9 !important;
  border-radius:16px !important;
  background:#fff !important;
  box-shadow:0 8px 28px rgba(26,31,54,.05) !important;
}

.directory-header {
  min-height:84px !important;
  padding:18px 20px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;
  border-bottom:1px solid #ccfbf1 !important;
  background:linear-gradient(90deg,#f0fdfa,#ffffff) !important;
}

.directory-eyebrow {
  color:#0f766e !important;
}

.directory-title {
  margin-top:3px !important;
  color:#172033 !important;
  font-size:17px !important;
  font-weight:900 !important;
}

.directory-subtitle {
  margin-top:3px !important;
  color:#7a8798 !important;
  font-size:10px !important;
}

.directory-record-count {
  padding:7px 10px !important;
  border:1px solid #c7d2fe !important;
  border-radius:20px !important;
  background:#eef2ff !important;
  color:#4338ca !important;
  font-size:9px !important;
  font-weight:800 !important;
}

.application-table-wrapper {
  width:100% !important;
  overflow:auto !important;
}

.application-table {
  width:100% !important;
  min-width:1120px !important;
  border-collapse:collapse !important;
}

.application-table thead {
  background:#f0fdfa !important;
}

.application-table th {
  padding:13px 14px !important;
  border-bottom:1px solid #99f6e4 !important;
  color:#0f766e !important;
  font-size:9px !important;
  font-weight:900 !important;
  text-align:left !important;
  white-space:nowrap !important;
  letter-spacing:.35px !important;
}

.application-table tbody tr {
  border-bottom:1px solid #edf2f4 !important;
  transition:.15s ease !important;
}

.application-table tbody tr:hover {
  background:#fff7f8 !important;
}

.application-table td {
  padding:14px !important;
  color:#334155 !important;
  font-size:10px !important;
  vertical-align:middle !important;
}

.student-cell {
  display:flex !important;
  align-items:center !important;
  gap:9px !important;
}

.student-avatar {
  width:36px !important;
  height:36px !important;
  min-width:36px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border-radius:50% !important;
  background:#ccfbf1 !important;
  color:#0f766e !important;
  font-size:9px !important;
  font-weight:900 !important;
}

.student-name {
  color:#172033 !important;
  font-size:11px !important;
  font-weight:800 !important;
}

.student-id {
  margin-top:2px !important;
  color:#94a3b8 !important;
  font-size:8px !important;
}

.application-id {
  color:#be123c !important;
  font-weight:900 !important;
}

.application-number,
.opportunity-id {
  margin-top:3px !important;
  color:#94a3b8 !important;
  font-size:8px !important;
}

.opportunity-name {
  color:#4338ca !important;
  font-weight:800 !important;
}

.company-name {
  color:#be123c !important;
  font-weight:800 !important;
}

.country-name {
  color:#475569 !important;
  font-weight:700 !important;
}

.country-icon {
  margin-right:5px !important;
  color:#0f766e !important;
}

.status-pill,
.response-pill,
.shortlisted-pill {
  display:inline-flex !important;
  align-items:center !important;
  gap:4px !important;
  padding:5px 8px !important;
  border-radius:20px !important;
  font-size:8px !important;
  font-weight:800 !important;
  white-space:nowrap !important;
}

.status-pending {
  background:#fef3c7 !important;
  color:#b45309 !important;
}

.status-approved {
  background:#ccfbf1 !important;
  color:#0f766e !important;
}

.status-rejected {
  background:#ffe4e6 !important;
  color:#be123c !important;
}

.status-withdrawn {
  background:#f1f5f9 !important;
  color:#64748b !important;
}

.status-default {
  background:#eef2ff !important;
  color:#4338ca !important;
}

.response-positive {
  background:#ccfbf1 !important;
  color:#0f766e !important;
}

.response-negative {
  background:#ffe4e6 !important;
  color:#be123c !important;
}

.response-neutral,
.response-default {
  background:#f1f5f9 !important;
  color:#64748b !important;
}

.is-shortlisted {
  background:#ccfbf1 !important;
  color:#0f766e !important;
}

.not-shortlisted {
  background:#f1f5f9 !important;
  color:#64748b !important;
}

.date-value {
  color:#64748b !important;
  white-space:nowrap !important;
}

.view-button {
  height:31px !important;
  padding:0 10px !important;
  border:1px solid #c7d2fe !important;
  border-radius:8px !important;
  background:#eef2ff !important;
  color:#4338ca !important;
  font-size:9px !important;
  font-weight:800 !important;
  cursor:pointer !important;
}

.view-button:hover {
  background:#e0e7ff !important;
}

.empty-state {
  padding:55px 20px !important;
  text-align:center !important;
}

.empty-state-icon {
  width:54px !important;
  height:54px !important;
  margin:0 auto 12px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border-radius:15px !important;
  background:#f0fdfa !important;
  color:#0f766e !important;
  font-size:22px !important;
}

.empty-state-title {
  color:#172033 !important;
  font-size:14px !important;
  font-weight:900 !important;
}

.empty-state-text {
  margin-top:5px !important;
  color:#7a8798 !important;
  font-size:10px !important;
}

.empty-state-button {
  margin-top:14px !important;
  padding:9px 14px !important;
  border:0 !important;
  border-radius:8px !important;
  background:#0f766e !important;
  color:#fff !important;
  font-size:10px !important;
  font-weight:800 !important;
}

/* ================= LOADING ================= */

.loading-area {
  min-height:250px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  gap:10px !important;
  color:#64748b !important;
  font-size:11px !important;
}

.spinner {
  width:22px !important;
  height:22px !important;
  border:3px solid #dbeafe !important;
  border-top-color:#4f46e5 !important;
  border-radius:50% !important;
  animation:c360Spin .7s linear infinite !important;
}

@keyframes c360Spin {
  to { transform:rotate(360deg); }
}

/* ================= NOTIFICATION RESULT ================= */

.notification-result {
  margin-top:12px !important;
  padding:11px 14px !important;
  border-radius:10px !important;
  font-size:10px !important;
  font-weight:700 !important;
}

.notification-result i {
  margin-right:6px !important;
}

.notification-success {
  background:#ecfdf5 !important;
  border:1px solid #a7f3d0 !important;
  color:#047857 !important;
}

.notification-error {
  background:#fff1f2 !important;
  border:1px solid #fecdd3 !important;
  color:#be123c !important;
}

/* ================= APPLICATION MODAL ================= */

.modal-backdrop {
  position:fixed !important;
  inset:0 !important;
  z-index:1000000 !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  padding:30px !important;
  background:rgba(15,23,42,.58) !important;
  backdrop-filter:blur(4px) !important;
}

.application-modal {
  width:min(1100px,96vw) !important;
  max-height:92vh !important;
  display:flex !important;
  flex-direction:column !important;
  overflow:hidden !important;
  border-radius:18px !important;
  background:#fff !important;
  box-shadow:0 30px 90px rgba(0,0,0,.28) !important;
}

.modal-top {
  min-height:76px !important;
  padding:15px 20px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;
  border-bottom:1px solid #e2e8f0 !important;
}

.modal-heading {
  display:flex !important;
  align-items:center !important;
  gap:12px !important;
}

.modal-heading-icon {
  width:42px !important;
  height:42px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border-radius:12px !important;
  background:#ccfbf1 !important;
  color:#0f766e !important;
}

.modal-eyebrow {
  color:#0f766e !important;
  font-size:8px !important;
  font-weight:900 !important;
  letter-spacing:.8px !important;
}

.modal-title {
  margin-top:3px !important;
  color:#172033 !important;
