}

.notification-highlight-title {
  margin-top:3px !important;
  color:#134e4a !important;
  font-size:11px !important;
  font-weight:800 !important;
}

.notification-highlight-text {
  margin-top:5px !important;
  color:#64748b !important;
  font-size:10px !important;
  line-height:1.5 !important;
}

.notification-modal-stats {
  display:grid !important;
  grid-template-columns:1fr 1fr !important;
  gap:10px !important;
  margin-top:12px !important;
}

.notification-modal-stat {
  padding:13px !important;
  display:flex !important;
  align-items:center !important;
  gap:10px !important;
  border-radius:11px !important;
}

.teal-stat {
  background:#f0fdfa !important;
  border:1px solid #99f6e4 !important;
}

.indigo-stat {
  background:#eef2ff !important;
  border:1px solid #c7d2fe !important;
}

.notification-modal-stat-icon {
  width:34px !important;
  height:34px !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  border-radius:9px !important;
}

.teal-stat .notification-modal-stat-icon {
  background:#ccfbf1 !important;
  color:#0f766e !important;
}

.indigo-stat .notification-modal-stat-icon {
  background:#e0e7ff !important;
  color:#4f46e5 !important;
}

.notification-modal-stat strong {
  display:block !important;
  color:#172033 !important;
  font-size:17px !important;
  font-weight:900 !important;
}

.notification-modal-stat span {
  display:block !important;
  margin-top:2px !important;
  color:#64748b !important;
  font-size:8px !important;
  font-weight:700 !important;
}

.notification-dispatch-box {
  margin-top:13px !important;
  padding:14px !important;
  border:1px solid #e2e8f0 !important;
  border-radius:11px !important;
  background:#f8fafc !important;
}

.notification-dispatch-title {
  color:#475569 !important;
  font-size:9px !important;
  font-weight:900 !important;
  letter-spacing:.6px !important;
}

.notification-dispatch-title i {
  margin-right:5px !important;
  color:#4f46e5 !important;
}

.notification-dispatch-box p {
  margin:7px 0 0 !important;
  color:#64748b !important;
  font-size:10px !important;
  line-height:1.6 !important;
}

.notification-modal-message {
  margin-top:12px !important;
  padding:11px 13px !important;
  border-radius:9px !important;
  font-size:10px !important;
  font-weight:700 !important;
}

.notification-modal-message i {
  margin-right:6px !important;
}

.notification-modal-success {
  background:#ecfdf5 !important;
  border:1px solid #a7f3d0 !important;
  color:#047857 !important;
}

.notification-modal-error {
  background:#fff1f2 !important;
  border:1px solid #fecdd3 !important;
  color:#be123c !important;
}

.notification-modal-footer {
  min-height:65px !important;
  padding:12px 18px !important;
  display:flex !important;
  justify-content:flex-end !important;
  align-items:center !important;
  gap:9px !important;
  border-top:1px solid #e2e8f0 !important;
  background:#f8fafc !important;
}

.secondary-btn,
.primary-btn {
  height:37px !important;
  padding:0 15px !important;
  border-radius:9px !important;
  font-size:10px !important;
  font-weight:800 !important;
  cursor:pointer !important;
}

.secondary-btn {
  border:1px solid #d7dee7 !important;
  background:#fff !important;
  color:#475569 !important;
}

.primary-btn {
  border:0 !important;
  background:#0f766e !important;
  color:#fff !important;
}

.primary-btn:hover {
  background:#115e59 !important;
}

.primary-btn:disabled {
  opacity:.55 !important;
  cursor:not-allowed !important;
}

/* ================= COLLAPSED SIDEBAR ================= */

.sidebar-collapsed .applications-sidebar {
  width:78px !important;
  min-width:78px !important;
}

.sidebar-collapsed .brand-copy,
.sidebar-collapsed .sidebar-user-info,
.sidebar-collapsed .menu-section-title,
.sidebar-collapsed .menu-item > span:not(.menu-icon),
.sidebar-collapsed .menu-count,
.sidebar-collapsed .sidebar-footer {
  display:none !important;
}

.sidebar-collapsed .sidebar-brand {
  justify-content:center !important;
  padding:18px 10px !important;
}

.sidebar-collapsed .sidebar-user-card {
  justify-content:center !important;
  margin-left:10px !important;
  margin-right:10px !important;
}

.sidebar-collapsed .menu-item {
  justify-content:center !important;
  padding:0 !important;
}

.sidebar-collapsed .menu-icon {
  width:auto !important;
}

/* ================= RESPONSIVE ================= */

@media (max-width:1200px) {

  .kpi-grid {
    grid-template-columns:repeat(2,minmax(0,1fr)) !important;
  }

  .application-summary-strip,
  .details-grid,
  .edit-grid {
    grid-template-columns:repeat(2,minmax(0,1fr)) !important;
  }

  .topbar-search {
    width:220px !important;
  }

}

@media (max-width:900px) {

  .applications-sidebar {
    width:230px !important;
    min-width:230px !important;
  }

  .applications-content {
    padding:22px 18px 40px !important;
  }

  .page-heading {
    align-items:flex-start !important;
    flex-direction:column !important;
  }

  .notification-panel {
    align-items:flex-start !important;
    flex-direction:column !important;
  }

  .notification-stats {
    width:100% !important;
    justify-content:space-between !important;
  }

  .topbar-search {
    display:none !important;
  }

}

@media (max-width:700px) {

  .applications-sidebar {
    position:absolute !important;
    left:0 !important;
    top:0 !important;
    bottom:0 !important;
    z-index:1000 !important;
  }

  .sidebar-collapsed .applications-sidebar {
    width:0 !important;
    min-width:0 !important;
    overflow:hidden !important;
  }

  .applications-topbar {
    padding:0 12px !important;
  }

  .topbar-profile-text,
  .profile-arrow {
    display:none !important;
  }

  .kpi-grid {
    grid-template-columns:1fr !important;
  }

  .notification-modal-stats,
  .application-summary-strip,
  .details-grid,
  .edit-grid {
    grid-template-columns:1fr !important;
  }

  .detail-wide {
    grid-column:auto !important;
  }

  .page-heading-actions {
    width:100% !important;
    flex-direction:column !important;
  }

  .outline-button {
    width:100% !important;
    justify-content:center !important;
  }

}

sp_widget.script:
(function() {

  /* =========================================================
     CAMPUS360 TPO APPLICATION MANAGEMENT
     =========================================================

     TABLES:

       student_application
       student_master
       placement_opportunity
       company_master

     FEATURES:

       - Application Directory
       - Student -> Opportunity mapping
       - Company filter
       - Country filter
       - Application Status filter
       - Full application view
       - Application update
       - Eligible student detection
       - Notification queueing

     ========================================================= */


  /* =========================================================
     TABLE NAMES
     ========================================================= */

  var APPLICATION_TABLE =
    "student_application";


  var STUDENT_TABLE =
    "student_master";


  var OPPORTUNITY_TABLE =
    "placement_opportunity";


  var COMPANY_TABLE =
    "company_master";


  /*
   * Event that must be registered in ServiceNow:
   *
   * campus360.student.opportunity.reminder
   *
   * The notification can use:
   *   parm1 = student email
   *   parm2 = notification body
   */
  var NOTIFICATION_EVENT =
    "campus360.student.opportunity.reminder";


  /* =========================================================
     VALID TABLE HELPER
     ========================================================= */

  function getValidTable(
    normalName,
    scopedName
  ) {

    var gr =
      new GlideRecord(normalName);


    if (gr.isValid()) {
      return normalName;
    }


    var scopedGR =
      new GlideRecord(scopedName);


    if (scopedGR.isValid()) {
      return scopedName;
    }


    return normalName;

  }


  APPLICATION_TABLE =
    getValidTable(
      "student_application",
      "x_snc_campus360_student_application"
    );


  STUDENT_TABLE =
    getValidTable(
      "student_master",
      "x_snc_campus360_student_master"
    );


  OPPORTUNITY_TABLE =
    getValidTable(
      "placement_opportunity",
      "x_snc_campus360_placement_opportunity"
    );


  COMPANY_TABLE =
    getValidTable(
      "company_master",
      "x_snc_campus360_company_master"
    );


  /* =========================================================
     DATA
     ========================================================= */

  data.applications = [];

  data.companies = [];

  data.countries = [];


  data.choices = {

    applicationStatus: [],

    studentResponse: [],

    assessmentStatus: [],

    interviewStatus: [],

    offerStatus: []

  };


  data.summary = {

    totalApplications: 0,

    pendingApplications: 0,

    shortlistedApplications: 0,

    offerApplications: 0

  };


  data.notification = {

    eligibleStudents: 0,

    eligibleOpportunities: 0,

    message: ""

  };


  /* =========================================================
     CHOICE HELPER
     ========================================================= */

  function addChoice(
    list,
    value,
    label
  ) {

    value =
      String(value || "");


    label =
      String(label || value);


    if (!value) {
      return;
    }


    for (
      var i = 0;
      i < list.length;
      i++
    ) {

      if (
        String(list[i].value) === value
      ) {

        return;

      }

    }


    list.push({

      value: value,

      label: label

    });

  }


  /* =========================================================
     SIMPLE OPTION
     ========================================================= */

  function addSimpleOption(
    list,
    value,
    label
  ) {

    value =
      String(value || "").trim();


    label =
      String(label || value).trim();


    if (!value) {
      return;
    }


    for (
      var i = 0;
      i < list.length;
      i++
    ) {

      if (
        String(list[i].value).toLowerCase() ===
        value.toLowerCase()
      ) {

        return;

      }

    }


    list.push({

      value: value,

      label: label

    });

  }


  /* =========================================================
     SAFE VALUE
     ========================================================= */

  function getValue(
    gr,
    fieldName
  ) {

    if (

      !gr ||

      !fieldName ||

      !gr.isValidField(fieldName)

    ) {

      return "";

    }


    return String(
      gr.getValue(fieldName) || ""
    );

  }


  /* =========================================================
     SAFE DISPLAY
     ========================================================= */

  function getDisplay(
    gr,
    fieldName
  ) {

    if (

      !gr ||

      !fieldName ||

      !gr.isValidField(fieldName)

    ) {

      return "";

    }


    return String(
      gr.getDisplayValue(fieldName) || ""
    );

  }


  /* =========================================================
     DATE DISPLAY
     ========================================================= */

  function getDateDisplay(
    gr,
    fieldName
  ) {

    if (

      !gr ||

      !fieldName ||

      !gr.isValidField(fieldName)

    ) {

      return "";

    }


    if (!gr.getValue(fieldName)) {
      return "";
    }


    return String(
      gr.getDisplayValue(fieldName) || ""
    );

  }


  /* =========================================================
     BOOLEAN
     ========================================================= */

  function getBoolean(
    gr,
    fieldName
  ) {

    var value =
      getValue(
        gr,
        fieldName
      ).toLowerCase();


    return (

      value === "true" ||

      value === "1"

    );

  }


  /* =========================================================
     REFERENCE
     ========================================================= */

  function getReference(
    gr,
    fieldName
  ) {

    if (

      !gr ||

      !fieldName ||

      !gr.isValidField(fieldName)

    ) {

      return null;

    }


    try {

      var element =
        gr.getElement(fieldName);


      if (!element) {
        return null;
      }


      var reference =
        element.getRefRecord();


      if (

        reference &&

        reference.isValidRecord()

      ) {

        return reference;

      }

    } catch (e) {

      return null;

    }


    return null;

  }


  /* =========================================================
     STUDENT
     ========================================================= */

  function getStudent(
    applicationGR
  ) {

    var result = {

      sys_id: "",

      name: "",

      student_id: "",

      email: "",

      phone: "",

      batch: "",

      branch: "",

      degree: "",

      cgpa: ""

    };


    var studentGR =
      getReference(
        applicationGR,
        "student"
      );


    if (!studentGR) {
      return result;
    }


    result.sys_id =
      studentGR.getUniqueValue();


    result.name =
      getValue(
        studentGR,
        "student_name"
      );


    result.student_id =
      getValue(
        studentGR,
        "student_id"
      );


    result.email =
      getValue(
        studentGR,
        "email"
      );


    result.phone =
      getValue(
        studentGR,
        "phone_number"
      );


    result.batch =
      getValue(
        studentGR,
        "batch"
      );


    result.branch =
      getDisplay(
        studentGR,
        "branch"
      );


    result.degree =
      getDisplay(
        studentGR,
        "degree"
      );


    result.cgpa =
      getValue(
        studentGR,
        "cgpa"
      );


    return result;

  }


  /* =========================================================
     COMPANY
     ========================================================= */

  function getCompany(
    opportunityGR
  ) {

    var companyGR =
      getReference(
        opportunityGR,
        "company"
      );


    if (!companyGR) {
      return {
        sys_id: "",
        name: ""
      };
    }


    return {

      sys_id:
        companyGR.getUniqueValue(),

      name:
        getValue(
          companyGR,
          "company_name"
        )

    };

  }


  /* =========================================================
     OPPORTUNITY
     ========================================================= */

  function getOpportunity(
    applicationGR
  ) {

    var result = {

      sys_id: "",

      opportunity_id: "",

      opportunity_title: "",

      opportunity_type: "",

      company_name: "",

      country: "",

      location: "",

      ctc_stipend: "",

      minimum_cgpa: "",

      application_deadline_display: "",

      drive_date_display: ""

    };


    var opportunityGR =
      getReference(
        applicationGR,
        "opportunity"
      );


    if (!opportunityGR) {
      return result;
    }


    result.sys_id =
      opportunityGR.getUniqueValue();


    result.opportunity_id =
      getValue(
        opportunityGR,
        "opportunity_id"
      );


    result.opportunity_title =
      getValue(
        opportunityGR,
        "opportunity_title"
      );


    result.opportunity_type =
      getDisplay(
        opportunityGR,
        "opportunity_type"
      );


    var company =
      getCompany(
        opportunityGR
      );


    result.company_name =
      company.name;


    /*
     * Country is read safely.
     *
     * If your placement_opportunity table
     * does not contain a country field,
     * this simply returns blank.
     */
    result.country =
      getDisplay(
        opportunityGR,
        "country"
      ) ||
      getValue(
        opportunityGR,
        "country"
      );


    result.location =
      getValue(
        opportunityGR,
        "location"
      );


    result.ctc_stipend =
      getValue(
        opportunityGR,
        "ctc_stipend"
      );


    result.minimum_cgpa =
      getValue(
        opportunityGR,
        "minimum_cgpa"
      );


    result.application_deadline_display =
      getDateDisplay(
        opportunityGR,
        "application_deadline"
      );


    result.drive_date_display =
      getDateDisplay(
        opportunityGR,
        "drive_date"
      );


    return result;

  }


  /* =========================================================
     BUILD APPLICATION
     ========================================================= */

  function buildApplication(
    gr
  ) {

    var student =
      getStudent(gr);


    var opportunity =
      getOpportunity(gr);


    var applicationStatusValue =
      getValue(
        gr,
        "application_status"
      );


    var applicationStatusDisplay =
      getDisplay(
        gr,
        "application_status"
      );


    var studentResponseValue =
      getValue(
        gr,
        "student_response"
      );


    var studentResponseDisplay =
      getDisplay(
        gr,
        "student_response"
      );


    var assessmentValue =
      getValue(
        gr,
        "assessment_status"
      );


    var assessmentDisplay =
      getDisplay(
        gr,
        "assessment_status"
      );


    var interviewValue =
      getValue(
        gr,
        "interview_status"
      );


    var interviewDisplay =
      getDisplay(
        gr,
        "interview_status"
      );


    var offerValue =
      getValue(
        gr,
        "offer_status"
      );


    var offerDisplay =
      getDisplay(
        gr,
        "offer_status"
      );


    return {

      sys_id:
        gr.getUniqueValue(),


      number:
        getValue(
          gr,
          "number"
        ),


      application_id:
        getValue(
          gr,
          "application_id"
        ),


      application_status:
        applicationStatusDisplay,


      application_status_value:
        applicationStatusValue,


      student_response:
        studentResponseDisplay,


      student_response_value:
        studentResponseValue,


      assessment_status:
        assessmentDisplay,


      assessment_status_value:
        assessmentValue,


      interview_status:
        interviewDisplay,


      interview_status_value:
        interviewValue,


      offer_status:
        offerDisplay,


      offer_status_value:
        offerValue,


      shortlisted:
        getBoolean(
          gr,
          "shortlisted"
        ),


      ai_match_score:
        parseInt(
          getValue(
            gr,
            "ai_match_score"
          ),
          10
        ) || 0,


      reminder_count:
        parseInt(
          getValue(
            gr,
            "reminder_count"
          ),
          10
        ) || 0,


      applied_date:
        getValue(
          gr,
          "applied_date"
        ),


      applied_date_display:
        getDateDisplay(
          gr,
          "applied_date"
        ),


      last_reminder:
        getValue(
          gr,
          "last_reminder"
        ),


      last_reminder_display:
        getDateDisplay(
          gr,
          "last_reminder"
        ),


      student_sys_id:
        student.sys_id,


      student_name:
        student.name,


      student_id:
        student.student_id,


      student_email:
        student.email,


      student_phone:
        student.phone,


      student_batch:
        student.batch,


      student_branch:
        student.branch,


      student_degree:
        student.degree,


      student_cgpa:
        student.cgpa,


      opportunity_sys_id:
        opportunity.sys_id,


      opportunity_id:
        opportunity.opportunity_id,


      opportunity_title:
        opportunity.opportunity_title,


      opportunity_type:
        opportunity.opportunity_type,


      company_name:
        opportunity.company_name,


      country:
        opportunity.country,


      location:
        opportunity.location,


      ctc_stipend:
        opportunity.ctc_stipend,


      minimum_cgpa:
        opportunity.minimum_cgpa,


      application_deadline_display:
        opportunity.application_deadline_display,


      drive_date_display:
        opportunity.drive_date_display

    };

  }


  /* =========================================================
     LOAD APPLICATIONS
     ========================================================= */

  function loadApplications() {

    data.applications = [];

    data.companies = [];

    data.countries = [];


    var gr =
      new GlideRecord(
        APPLICATION_TABLE
      );


    if (!gr.isValid()) {

      data.error =
        "Student Application table could not be opened.";

      return;

    }


    gr.query();


    while (gr.next()) {

      var application =
        buildApplication(gr);


      data.applications.push(
        application
      );


      addChoice(
        data.choices.applicationStatus,
        application.application_status_value,
        application.application_status
      );


      addChoice(
        data.choices.studentResponse,
        application.student_response_value,
        application.student_response
      );


      addChoice(
        data.choices.assessmentStatus,
        application.assessment_status_value,
        application.assessment_status
      );


      addChoice(
        data.choices.interviewStatus,
        application.interview_status_value,
        application.interview_status
      );


      addChoice(
        data.choices.offerStatus,
        application.offer_status_value,
        application.offer_status
      );


      addSimpleOption(
        data.companies,
        application.company_name,
        application.company_name
      );


      addSimpleOption(
        data.countries,
        application.country,
        application.country
      );

    }


    calculateSummary();

  }


  /* =========================================================
     SUMMARY
     ========================================================= */

  function calculateSummary() {

    data.summary = {

      totalApplications:
        data.applications.length,

      pendingApplications:
        0,

      shortlistedApplications:
        0,

      offerApplications:
        0

    };


    for (
      var i = 0;
      i < data.applications.length;
      i++
    ) {

      var application =
        data.applications[i];


      if (

        String(
          application.application_status || ""
        )
        .toLowerCase() ===
        "pending"

      ) {

        data.summary.pendingApplications++;

      }


      if (application.shortlisted) {

        data.summary.shortlistedApplications++;

      }


      if (application.offer_status_value) {

        data.summary.offerApplications++;

      }

    }

  }


  /* =========================================================
     UPDATE APPLICATION
     ========================================================= */

  function updateApplication(
    incoming
  ) {

    var result = {

      success:false,

      message:"",

      application:null

    };


    if (
      !incoming ||
      !incoming.sys_id
    ) {

      result.message =
        "Application record was not identified.";

      return result;

    }


    var gr =
      new GlideRecord(
        APPLICATION_TABLE
      );


    if (
      !gr.get(
        incoming.sys_id
      )
    ) {

      result.message =
        "Application record could not be found.";

      return result;

    }


    var fields = [

      "application_status",

      "student_response",

      "assessment_status",

      "interview_status",

      "offer_status"

    ];


    for (
      var i = 0;
      i < fields.length;
      i++
    ) {

      if (
        gr.isValidField(fields[i])
      ) {

        gr.setValue(
          fields[i],
          incoming[fields[i]] || ""
        );

      }

    }


    if (
      gr.isValidField("shortlisted")
    ) {

      gr.setValue(

        "shortlisted",

        incoming.shortlisted
          ? "true"
          : "false"

      );

    }


    var updatedSysId =
      gr.update();


    if (!updatedSysId) {

      result.message =
        "Application could not be updated.";

      return result;

    }


    var updatedGR =
      new GlideRecord(
        APPLICATION_TABLE
      );


    if (
      updatedGR.get(
        updatedSysId
      )
    ) {

      result.application =
        buildApplication(
          updatedGR
        );

    }


    result.success = true;

    result.message =
      "Application updated successfully.";


    return result;

  }


  /* =========================================================
     NUMBER HELPER
     ========================================================= */

  function parseNumber(
    value
  ) {

    var n =
      parseFloat(
        String(value || "")
          .replace(
            /[^0-9.\-]/g,
            ""
          )
      );


    return isNaN(n)
      ? null
      : n;

  }


  /* =========================================================
     LIST HELPER
     ========================================================= */

  function splitList(
    value
  ) {

    var raw =
      String(value || "")
        .split(/[,;\n]/);


    var output = [];


    for (
      var i = 0;
      i < raw.length;
      i++
    ) {

      var item =
        String(raw[i] || "")
          .trim()
          .toLowerCase();


      if (item) {

        output.push(item);

      }

    }


    return output;

  }


  /* =========================================================
     BRANCH ELIGIBILITY
     ========================================================= */

  function branchEligible(
    studentGR,
    opportunityGR
  ) {

    if (
      !opportunityGR.isValidField(
        "eligible_branches"
      )
    ) {

      return true;

    }


    var required =
      getValue(
        opportunityGR,
        "eligible_branches"
      );


    if (!required) {
      return true;
    }


    var list =
      splitList(required);


    if (!list.length) {
      return true;
    }


    var branchValue =
      getValue(
        studentGR,
        "branch"
      ).toLowerCase();


    var branchDisplay =
      getDisplay(
        studentGR,
        "branch"
      ).toLowerCase();


    for (
      var i = 0;
      i < list.length;
      i++
    ) {

      if (

        list[i] === branchValue ||

        list[i] === branchDisplay

      ) {

        return true;

      }

    }


    return false;

  }


  /* =========================================================
     OPPORTUNITY OPEN
     ========================================================= */

  function opportunityOpen(
    opportunityGR
  ) {

    var status =
      getDisplay(
        opportunityGR,
        "status"
      ) ||
      getValue(
        opportunityGR,
        "status"
      );


    if (

      status &&

      status.toLowerCase() !== "open"

    ) {

      return false;

    }


    var deadline =
      getValue(
        opportunityGR,
        "application_deadline"
      );


    if (deadline) {

      try {

        var deadlineGdt =
          new GlideDateTime(
            deadline
          );


        var now =
          new GlideDateTime();


        if (

          deadlineGdt.getNumericValue() <

          now.getNumericValue()

        ) {

          return false;

        }

      } catch (e) {

        /*
         * If the date cannot be parsed,
         * do not block the opportunity.
         */

      }

    }


    return true;

  }


  /* =========================================================
     STUDENT ELIGIBILITY
     ========================================================= */

  function studentEligibleForOpportunity(
    studentGR,
    opportunityGR
  ) {

    if (
      !opportunityOpen(
        opportunityGR
      )
    ) {

      return false;

    }


    var minimumCgpa =
      parseNumber(
        getValue(
          opportunityGR,
          "minimum_cgpa"
        )
      );


    var studentCgpa =
      parseNumber(
        getValue(
          studentGR,
          "cgpa"
        )
      );


    if (

      minimumCgpa !== null &&

      (

        studentCgpa === null ||

        studentCgpa < minimumCgpa

      )

    ) {

      return false;

    }


    if (
      !branchEligible(
        studentGR,
        opportunityGR
      )
    ) {

      return false;

    }


    return true;

  }


  /* =========================================================
     APPLIED STUDENT MAP
     ========================================================= */

  function buildAppliedStudentMap() {

    var map = {};


    var gr =
      new GlideRecord(
        APPLICATION_TABLE
      );


    if (!gr.isValid()) {
      return map;
    }


    gr.query();


    while (gr.next()) {

      var studentGR =
        getReference(
          gr,
          "student"
        );


      if (studentGR) {

        map[
          studentGR.getUniqueValue()
        ] = true;

      }

    }


    return map;

  }


  /* =========================================================
     GET ELIGIBLE STUDENTS
     WHO HAVE NOT APPLIED ANYWHERE
     ========================================================= */

  function getEligibleStudentsWithoutApplications() {

    var result = [];


    var appliedMap =
      buildAppliedStudentMap();


    var opportunities = [];


    var opportunityGR =
      new GlideRecord(
        OPPORTUNITY_TABLE
      );


    if (
      opportunityGR.isValid()
    ) {

      opportunityGR.query();


      while (
        opportunityGR.next()
      ) {

        if (
          opportunityOpen(
            opportunityGR
          )
        ) {

          opportunities.push(
            opportunityGR.getUniqueValue()
          );

        }

      }

    }


    var studentGR =
      new GlideRecord(
        STUDENT_TABLE
      );


    if (
      !studentGR.isValid()
    ) {

      return {

        students:result,

        opportunityCount:
          opportunities.length

      };

    }


    studentGR.query();


    while (
      studentGR.next()
    ) {

      var studentSysId =
        studentGR.getUniqueValue();


      /*
       * IMPORTANT:
       *
       * If this student has already applied
       * for ANY opportunity, do not include them.
       */

      if (
        appliedMap[studentSysId]
      ) {

        continue;

      }


      var eligible = [];


      for (
        var i = 0;
        i < opportunities.length;
        i++
      ) {

        var opp =
          new GlideRecord(
            OPPORTUNITY_TABLE
          );


        if (
          opp.get(
            opportunities[i]
          )
        ) {

          if (
            studentEligibleForOpportunity(
              studentGR,
              opp
            )
          ) {

            var companyName = "";


            var companyGR =
              getReference(
                opp,
                "company"
              );


            if (companyGR) {

              companyName =
                getValue(
                  companyGR,
                  "company_name"
                );

            }


            eligible.push({

              sys_id:
                opp.getUniqueValue(),

              title:
                getValue(
                  opp,
                  "opportunity_title"
                ),

              company:
                companyName,

              country:
                getDisplay(
                  opp,
                  "country"
                ) ||
                getValue(
                  opp,
                  "country"
                )

            });

          }

        }

      }


      if (
        eligible.length
      ) {

        result.push({

          sys_id:
            studentSysId,

          name:
            getValue(
              studentGR,
              "student_name"
            ),

          email:
            getValue(
              studentGR,
              "email"
            ),

          opportunities:
            eligible

        });

      }

    }


    return {

      students:result,

      opportunityCount:
        opportunities.length

    };

  }


  /* =========================================================
     NOTIFICATION SUMMARY
     ========================================================= */

  function loadNotificationSummary() {

    var info =
      getEligibleStudentsWithoutApplications();


    data.notification.eligibleStudents =
      info.students.length;


    data.notification.eligibleOpportunities =
      info.opportunityCount;


    return info;

  }


  /* =========================================================
     SEND ELIGIBLE STUDENT NOTIFICATIONS
     ========================================================= */

  function sendEligibleStudentNotifications() {

    var info =
      getEligibleStudentsWithoutApplications();


    var sent = 0;

    var skipped = 0;


    for (
      var i = 0;
      i < info.students.length;
      i++
    ) {

      var student =
        info.students[i];


      if (!student.email) {

        skipped++;

        continue;

      }


      var lines = [];


      for (
        var j = 0;
        j < student.opportunities.length;
        j++
      ) {

        var opp =
          student.opportunities[j];


        var line =
          "- " +
          (
            opp.title ||
            "Placement Opportunity"
          );


        if (opp.company) {

          line +=
            " | Company: " +
            opp.company;

        }


        if (opp.country) {

          line +=
            " | Country: " +
            opp.country;

        }


        lines.push(line);

      }


      var subject =
        "Campus360: Placement opportunities available for you";


      var body =

        "Hello " +

        (
          student.name ||
          "Student"
        ) +

        ",\n\n" +

        "Our placement records show that you have not applied for any placement opportunity yet. " +

        "You are currently eligible for the following open opportunity/opportunities:\n\n" +

        lines.join("\n") +

        "\n\n" +

        "Please review the opportunities in Campus360 and apply if you are interested." +

        "\n\n" +

        "Training & Placement Office" +

        "\nCampus360";


      try {

        var studentRecord =
          new GlideRecord(
            STUDENT_TABLE
          );


        if (
          studentRecord.get(
            student.sys_id
          )
        ) {

          /*
           * parm1 = email
           * parm2 = message body
           *
           * The ServiceNow Email Notification
           * associated with this event should
           * use these parameters.
           */

          gs.eventQueue(

            NOTIFICATION_EVENT,

            studentRecord,

            student.email,

            body

          );


          sent++;

        } else {

          skipped++;

        }

      } catch (e) {

        skipped++;

        gs.error(
          "Campus360 notification error: " +
          e.message
        );

      }

    }


    data.notification.eligibleStudents =
      info.students.length;


    data.notification.eligibleOpportunities =
      info.opportunityCount;


    data.notificationResult = {

      success:true,

      sent:sent,

      skipped:skipped,

      message:

        sent +

        " notification(s) queued." +

        (

          skipped

            ? " " +
              skipped +
              " student(s) were skipped because no usable email/record was found."

            : ""

        )

    };


    data.notification.message =
      data.notificationResult.message;

  }


  /* =========================================================
     UPDATE APPLICATION REQUEST
     ========================================================= */

  if (
    input &&
    input.action ===
      "update_application"
  ) {

    data.updateResult =
      updateApplication(
        input.application
      );


    loadApplications();

    loadNotificationSummary();


    if (

      data.updateResult &&

      data.updateResult.success

    ) {

      for (
        var i = 0;
        i < data.applications.length;
        i++
      ) {

        if (

          data.applications[i].sys_id ===

          input.application.sys_id

        ) {

          data.updateResult.application =
            data.applications[i];

          break;

        }

      }

    }


    return;

  }


  /* =========================================================
     SEND NOTIFICATION REQUEST
     ========================================================= */

  if (

    input &&

    input.action ===
      "notify_eligible_students"

  ) {

    loadApplications();

    sendEligibleStudentNotifications();

    return;

  }


  /* =========================================================
     NOTIFICATION SUMMARY REQUEST
     ========================================================= */

  if (

    input &&

    input.action ===
      "notification_summary"

  ) {

    loadApplications();

    loadNotificationSummary();

    return;

  }


  /* =========================================================
     NORMAL PAGE LOAD / REFRESH
     ========================================================= */

  loadApplications();

  loadNotificationSummary();


})();
